<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($title??'') ?></title><link rel="stylesheet" href="<?= e(url('assets/css/storefront.css')) ?>"></head><body class="storefront-body"><header class="storefront-header"><a class="brand" href="<?= e(url()) ?>"><?= e($settings['site_title']??'E-pin') ?></a><form class="header-search" method="get" action="<?= e(url('search')) ?>" role="search"><input type="search" name="q" value="<?= e($searchTerm??'') ?>" minlength="2" maxlength="80" placeholder="Oyun, ürün veya kategori ara" aria-label="Ürün ara"><button type="submit">Ara</button></form><button class="storefront-menu-toggle" type="button" aria-label="Menüyü aç" aria-expanded="false" aria-controls="storefront-navigation"><span></span><span></span><span></span></button><nav id="storefront-navigation" class="storefront-navigation" aria-label="Ana menü"><?php foreach(($menus??[]) as $menu): ?><?php if(($menu['menu_type']??'link')==='categories'): ?><details class="nav-category-menu"><summary><?= e($menu['title']) ?></summary><div class="nav-category-dropdown"><?php foreach(($categories??[]) as $c): ?><a href="<?= e(url('category/'.rawurlencode($c['slug']))) ?>"><?= e($c['name']) ?></a><?php endforeach; ?></div></details><?php else: ?><?php $href=preg_match('~^https?://~i',$menu['url'])?$menu['url']:url($menu['url']); ?><a class="nav-link" href="<?= e($href) ?>"><?= e($menu['title']) ?></a><?php endif; ?><?php endforeach; ?><a class="nav-link nav-cart-link" href="<?= e(url('cart')) ?>">Sepet <span>(<?= array_sum($_SESSION['cart']??[]) ?>)</span></a><?php if(!empty($_SESSION['user'])): ?><?php if(($_SESSION['user']['role']??'')==='admin'): ?><a href="<?= e(url('admin')) ?>">Yönetim</a><?php elseif(($_SESSION['user']['role']??'')==='seller'): ?><a href="<?= e(url('seller')) ?>">Satıcı paneli</a><a href="<?= e(url('account')) ?>">Hesabım</a><?php else: ?><a href="<?= e(url('account')) ?>">Hesabım</a><?php if(config('business_mode')==='multi_vendor'): ?><a href="<?= e(url('seller/apply')) ?>">Satıcı ol</a><?php endif; ?><?php endif; ?><form class="nav-logout-form" method="post" action="<?= e(url('logout')) ?>"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><button class="nav-logout" type="submit">Çıkış</button></form><?php else: ?><a href="<?= e(url('login')) ?>">Giriş</a><?php endif; ?></nav></header><main class="container"><?php if($m=flash('error')): ?><div class="alert"><?= e($m) ?></div><?php endif; ?><?php if($m=flash('success')): ?><div class="success"><?= e($m) ?></div><?php endif; ?><?php require APP_ROOT.'/app/views/'.$view.'.php'; ?></main><footer class="footer"><div class="footer-inner"><span><?= e($settings['footer_text']??'') ?></span><nav class="footer-links" aria-label="Alt bilgi bağlantıları"><?php foreach(($footerMenus??[]) as $menu): ?><?php $footerHref=preg_match('~^https?://~i',$menu['url'])?$menu['url']:url($menu['url']); ?><a href="<?= e($footerHref) ?>"><?= e($menu['title']) ?></a><?php endforeach; ?></nav></div></footer><script src="<?= e(url('assets/js/storefront.js')) ?>" defer></script></body></html>